import React, { useEffect, useState } from "react";

export default function UserProfileCard({ token, me: initialMe = {}, setMsg }) {
  const [me, setMe] = useState(initialMe);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (!token) return;
    setLoading(true);

    fetch((process.env.REACT_APP_API || "http://localhost:4000") + "/api/users/me", {
      headers: { Authorization: `Bearer ${token}` },
    })
      .then((res) => res.json())
      .then((data) => {
        setMe(data || {});
        setLoading(false);
      })
      .catch((err) => {
        console.error(err);
        setMsg && setMsg("Failed to load profile");
        setLoading(false);
      });
  }, [token, setMsg]);

  if (loading) {
    return (
      <div style={{ background: "#fff", padding: 12, borderRadius: 10, textAlign: "center" }}>
        Loading profile...
      </div>
    );
  }

  return (
    <div
      style={{
        background: "#fff",
        padding: 16,
        borderRadius: 10,
        textAlign: "center",
        boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
      }}
    >
      {/* Profile Icon */}
      <div
        style={{
          width: 70,
          height: 70,
          borderRadius: "50%",
          background: "#ddd",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: 30,
          margin: "0 auto 10px",
        }}
      >
        {me?.name ? me.name.charAt(0).toUpperCase() : "?"}
      </div>

      <div style={{ fontWeight: "bold", fontSize: 16 }}>{me?.name || "No Name"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 4 }}>{me?.email || "No Email"}</div>
      <div style={{ fontSize: 13, color: "#666", marginBottom: 8 }}>Role: {me?.role || "Member"}</div>

      {me?.points != null && (
        <div style={{ fontSize: 12, color: "#888" }}>
          Points: {me.points} —{" "}
          {me.points >= 200
            ? "Gold"
            : me.points >= 100
            ? "Silver"
            : me.points >= 50
            ? "Bronze"
            : me.points >= 10
            ? "Member"
            : "New"}
        </div>
      )}
    </div>
  );
}
